import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def set_parent(blueprint, parent):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.set_parent', json.dumps({'blueprint': blueprint, 'parent_class': parent}))

def compile_bp(blueprint):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': blueprint, 'warnings_as_errors': True}))

def get_parent(blueprint):
    return execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.get_parent', json.dumps({'blueprint': blueprint}))['returnValue']

def save(paths):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']

def run():
    paths = ['/ExtractionOps/Weapons/Rifle/GA_Weapon_Fire_ExtractionRifle', '/ExtractionOps/Weapons/Shotgun/GA_Weapon_Fire_ExtractionShotgun']
    parent = {'refPath': '/Script/ExtractionOpsRuntime.ExtractionGameplayAbility_RangedWeapon'}
    results = {}
    for path in paths:
        blueprint = load(path)
        set_parent(blueprint, parent)
        compile_bp(blueprint)
        results[path] = get_parent(blueprint)
    if not save(paths):
        raise RuntimeError('failed to save ranged ability assets')
    return {'parents': results, 'saved': True}
